/**
 * CIDR toolkit built on interval math.
 *
 * All addresses/ranges are handled as unsigned 32-bit integers (uint32 via >>> 0).
 * A range is [start, end] inclusive. CIDR blocks are "a.b.c.d/p" strings.
 */

/** Parse a dotted-quad IPv4 string to a uint32. */
export function ipToU32(ip: string): number {
  const parts = ip.split(".");
  if (parts.length !== 4) throw new Error(`invalid IPv4 address: ${ip}`);
  let out = 0;
  for (const part of parts) {
    if (!/^\d{1,3}$/.test(part)) throw new Error(`invalid IPv4 address: ${ip}`);
    const n = Number(part);
    if (n > 255) throw new Error(`invalid IPv4 address: ${ip}`);
    out = ((out << 8) | n) >>> 0;
  }
  return out >>> 0;
}

/** Format a uint32 as a dotted-quad IPv4 string. */
export function u32ToIp(value: number): string {
  const v = value >>> 0;
  return `${(v >>> 24) & 0xff}.${(v >>> 16) & 0xff}.${(v >>> 8) & 0xff}.${v & 0xff}`;
}

export type Range = readonly [start: number, end: number]; // inclusive, uint32

/** Convert a CIDR block to its inclusive [start, end] uint32 range. */
export function cidrToRange(cidr: string): Range {
  const match = /^(\d{1,3}(?:\.\d{1,3}){3})\/(\d{1,2})$/.exec(cidr);
  if (!match) throw new Error(`invalid CIDR: ${cidr}`);
  const prefix = Number(match[2]);
  if (prefix > 32) throw new Error(`invalid prefix length in ${cidr}`);
  const base = ipToU32(match[1]);
  const hostBits = 32 - prefix;
  // Mask off host bits (base must be the network address).
  const start = (hostBits === 0 ? base : (base & (0xffffffff << hostBits))) >>> 0;
  const end = (start + (hostBits === 0 ? 0xffffffff : (1 << hostBits) - 1)) >>> 0;
  return [start, end];
}

/** Convert an inclusive uint32 range to a CIDR block string. */
function rangeToCidr([start, end]: Range): string {
  const size = (end - start + 1) >>> 0; // power of two by construction
  let hostBits = 0;
  while (1 << hostBits < size) hostBits++;
  return `${u32ToIp(start)}/${32 - hostBits}`;
}

/**
 * Split an inclusive range into the minimal list of CIDR blocks covering it
 * exactly (greedy largest-aligned-block from each end).
 */
export function rangeToCidrs(start: number, end: number): string[] {
  let lo = start >>> 0;
  const hi = end >>> 0;
  if (lo > hi) return [];
  const out: string[] = [];
  while (lo <= hi) {
    // Largest aligned block starting at lo that doesn't pass hi.
    let hostBits = 0;
    while (hostBits < 32) {
      if ((lo & ((1 << (hostBits + 1)) - 1)) !== 0) break; // not aligned for a bigger block
      if (((lo + (1 << (hostBits + 1)) - 1) >>> 0) > hi && (lo + (1 << (hostBits + 1)) - 1) >= 0) {
        // careful with overflow at hi = 0xffffffff
        break;
      }
      hostBits++;
    }
    // The loop above can misbehave near overflow; recompute defensively.
    let size = 1;
    let hb = 0;
    while (hb < 32) {
      const nextSize = size * 2;
      const aligned = (lo % nextSize) === 0 || nextSize === 0x100000000;
      const fits = aligned && (nextSize - 1 <= 0xffffffff - lo);
      if (!fits) break;
      size = nextSize;
      hb++;
    }
    out.push(`${u32ToIp(lo)}/${32 - hb}`);
    lo = (lo + size) >>> 0;
  }
  return out;
}

/** Merge overlapping/touching ranges. Input need not be sorted. */
export function coalesceRanges(ranges: Range[]): Range[] {
  const sorted = ranges.map(([s, e]) => [s >>> 0, e >>> 0] as [number, number]).sort((a, b) => a[0] - b[0]);
  const out: Range[] = [];
  for (const [s, e] of sorted) {
    const last = out[out.length - 1];
    if (last && s <= last[1] + 1) {
      if (e > last[1]) out[out.length - 1] = [last[0], e];
    } else {
      out.push([s, e]);
    }
  }
  return out;
}

/**
 * Coalesce a list of CIDR blocks into the minimal equivalent list:
 * convert to ranges, merge touching/overlapping, convert back.
 */
export function coalesce(cidrs: string[]): string[] {
  return coalesceRanges(cidrs.map(cidrToRange)).flatMap(rangeToCidrs);
}

