import { describe, it, expect } from "vitest";
import { cidrToRange, rangeToCidrs, coalesce, u32ToIp, ipToU32, type Range } from "./cidr";

/** Tiny seeded PRNG (mulberry32). */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Merge overlapping/touching ranges; input sorted. Used as canonical form. */
function mergeSorted(ranges: Range[]): Range[] {
  const out: Range[] = [];
  for (const [s, e] of ranges) {
    const last = out[out.length - 1];
    if (last && s <= last[1] + 1) {
      if (e > last[1]) out[out.length - 1] = [last[0], e];
    } else {
      out.push([s, e]);
    }
  }
  return out;
}

/** Canonical address-set comparison: expand CIDRs to ranges, sort, merge. */
function canonical(ranges: Range[]): Range[] {
  return mergeSorted([...ranges].sort((a, b) => a[0] - b[0]));
}

describe("ip helpers", () => {
  it("round-trips dotted quads", () => {
    expect(u32ToIp(ipToU32("255.255.255.255"))).toBe("255.255.255.255");
    expect(u32ToIp(0)).toBe("0.0.0.0");
    expect(ipToU32("10.0.0.1")).toBe(0x0a000001);
  });
});

describe("cidrToRange", () => {
  it("computes inclusive bounds", () => {
    expect(cidrToRange("10.0.0.0/24")).toEqual([0x0a000000, 0x0a0000ff]);
    expect(cidrToRange("0.0.0.0/0")).toEqual([0, 0xffffffff]);
    expect(cidrToRange("192.168.1.7/32")).toEqual([0xc0a80107, 0xc0a80107]);
  });
});

describe("rangeToCidrs", () => {
  it("/32 single host", () => {
    expect(rangeToCidrs(0x0a000001, 0x0a000001)).toEqual(["10.0.0.1/32"]);
  });

  it("full space is a single /0", () => {
    expect(rangeToCidrs(0, 0xffffffff)).toEqual(["0.0.0.0/0"]);
  });

  it("adjacent-but-unalignable ranges stay split", () => {
    // [1..2] cannot merge with anything into an aligned block starting lower;
    // and a range like 10.0.0.1-10.0.0.254 needs many blocks.
    const got = rangeToCidrs(0x0a000001, 0x0a0000fe);
    expect(got).toEqual([
      "10.0.0.1/32",
      "10.0.0.2/31",
      "10.0.0.4/30",
      "10.0.0.8/29",
      "10.0.0.16/28",
      "10.0.0.32/27",
      "10.0.0.64/26",
      "10.0.0.128/25",
    ]);
    // Two adjacent single hosts that can't form a /31:
    expect(rangeToCidrs(3, 4)).toEqual(["0.0.0.3/32", "0.0.0.4/32"]);
  });
});

describe("coalesce", () => {
  it("merges two halves of a /24", () => {
    expect(coalesce(["10.0.0.0/25", "10.0.0.128/25"])).toEqual(["10.0.0.0/24"]);
  });

  it("leaves disjoint blocks untouched but sorted", () => {
    expect(coalesce(["192.168.0.0/24", "10.0.0.0/24"])).toEqual(["10.0.0.0/24", "192.168.0.0/24"]);
  });

  it("absorbs subnets contained in others", () => {
    expect(coalesce(["10.0.0.0/16", "10.0.42.0/24", "10.0.0.0/8"])).toEqual(["10.0.0.0/8"]);
  });

  it("full space collapses to 0.0.0.0/0", () => {
    expect(coalesce(["128.0.0.0/1", "0.0.0.0/1"])).toEqual(["0.0.0.0/0"]);
  });
});

describe("property: round-trip on seeded random ranges", () => {
  it("rangeToCidrs(start,end) -> expand covers exactly [start,end]", () => {
    const rand = mulberry32(0xc1d2);
    for (let i = 0; i < 300; i++) {
      const start = Math.floor(rand() * 0x100000000) >>> 0;
      const end = (start + Math.floor(rand() * (0x100000000 - start))) >>> 0;
      const cidrs = rangeToCidrs(start, end);
      const back = canonical(cidrs.map(cidrToRange));
      expect(back).toEqual([[start, end]]);
      // Minimality: no two output blocks share a parent prefix.
      for (let j = 1; j < cidrs.length; j++) {
        const [, e] = cidrToRange(cidrs[j - 1]);
        const [s] = cidrToRange(cidrs[j]);
        expect(s).toBe((e + 1) >>> 0);
      }
    }
  });

  it("cidrToRange -> rangeToCidrs returns the original block for any CIDR", () => {
    const rand = mulberry32(0xbeef);
    for (let i = 0; i < 300; i++) {
      const prefix = Math.floor(rand() * 33);
      const hostBits = 32 - prefix;
      // Random aligned network address.
      const net =
        prefix === 0 ? 0 : (((Math.floor(rand() * 0x100000000) << hostBits) & 0xffffffff) >>> 0);
      const cidr = `${u32ToIp(net)}/${prefix}`;
      const [s, e] = cidrToRange(cidr);
      expect(rangeToCidrs(s, e)).toEqual([cidr]);
    }
  });
});

describe("property: coalesce preserves the exact address set", () => {
  it("expanded output equals canonical input ranges", () => {
    const rand = mulberry32(0xcafe);
    for (let trial = 0; trial < 300; trial++) {
      const n = 1 + Math.floor(rand() * 8);
      const ranges: Range[] = [];
      for (let i = 0; i < n; i++) {
        const start = Math.floor(rand() * 0x10000000) >>> 0; // keep in low space
        const len = Math.floor(rand() * 4096);
        ranges.push([start, (start + len) >>> 0]);
      }
      const cidrsIn = ranges.flatMap(([s, e]) => rangeToCidrs(s, e));
      const out = coalesce(cidrsIn);
      expect(canonical(out.map(cidrToRange))).toEqual(canonical(ranges));
    }
  });
});

